# Rate history is append-only (PLAN G1b). The only permitted update is cancelling a row once
# (ADR-034); the service allows it only before the row takes effect.
TAX_RATE_SQL = """
CREATE FUNCTION catalog_tax_rate_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'catalog_producttaxrate is append-only' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.cancelled_at IS NOT NULL OR NEW.cancelled_at IS NULL
     OR (NEW.id, NEW.tenant_id, NEW.product_id, NEW.gst_rate, NEW.cess_type_id, NEW.cess_rate,
         NEW.effective_from, NEW.reason, NEW.created_at)
        IS DISTINCT FROM
        (OLD.id, OLD.tenant_id, OLD.product_id, OLD.gst_rate, OLD.cess_type_id, OLD.cess_rate,
         OLD.effective_from, OLD.reason, OLD.created_at) THEN
    RAISE EXCEPTION 'catalog_producttaxrate rows can only be cancelled' USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER catalog_tax_rate_guard
BEFORE UPDATE OR DELETE ON catalog_producttaxrate
FOR EACH ROW EXECUTE FUNCTION catalog_tax_rate_guard();
"""

