def seed_default_units(apps, schema_editor):
    Tenant = apps.get_model("platform", "Tenant")
    Unit = apps.get_model("catalog", "Unit")
    for tenant_id in Tenant.objects.values_list("id", flat=True):
        existing = set(Unit.objects.filter(tenant_id=tenant_id).values_list("code", flat=True))
        Unit.objects.bulk_create(
            [
                Unit(tenant_id=tenant_id, code=code, name=name, allows_decimal=dec, uqc=uqc)
                for code, name, dec, uqc in DEFAULT_UNITS
                if code not in existing
            ]
        )


